/*
 * A371806  Exponents k > 0 of powers of 2 such that the decimal expansion of
 *          2^k contains more than one nonoverlapping 666 substring.
 * https://oeis.org/A371806
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, base
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) generated by searching for exponents k such that 2^k
 * contains at least two nonoverlapping occurrences of the decimal
 * substring 666.  The function keeps the already found exponents
 * and extends the power of two incrementally. */

#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /* Pre‑computed exponents stored as idx_t to avoid
     * issues with arbitrary‑precision types in realloc. */
    static idx_t *terms = NULL;
    static size_t terms_cap = 0;
    static size_t terms_cnt = 0;

    /* Big‑integer in decimal, least significant digit first. */
    static uint8_t *digits = NULL;
    static size_t digits_cap = 0;
    static size_t digits_len = 0;
    static idx_t current_k = 0;

    /* Initialise on first call. */
    if (terms == NULL) {
        digits_cap = 1;
        digits_len = 1;
        digits = (uint8_t*)malloc(digits_cap);
        if (!digits) return 0;
        digits[0] = 1;                /* 2^0 = 1 */
    }

    /* Generate terms until we have at least n of them. */
    while (terms_cnt < n) {
        /* Next power of two: multiply current number by 2. */
        current_k++;
        uint16_t carry = 0;
        for (size_t i = 0; i < digits_len; i++) {
            uint16_t val = (uint16_t)digits[i] * 2 + carry;
            digits[i] = val % 10;
            carry = val / 10;
        }
        if (carry) {
            if (digits_len == digits_cap) {
                size_t new_cap = digits_cap * 2;
                uint8_t *tmp = (uint8_t*)realloc(digits, new_cap);
                if (!tmp) return 0;
                digits = tmp;
                digits_cap = new_cap;
            }
            digits[digits_len++] = carry;
        }

        /* Count non‑overlapping "666" substrings. */
        int count = 0;
        int i = (int)digits_len - 1;            /* most significant digit */
        while (i >= 2) {
            if (digits[i] == 6 && digits[i-1] == 6 && digits[i-2] == 6) {
                count++;
                if (count >= 2) break;
                i -= 3;                         /* skip these digits */
            } else {
                i--;
            }
        }

        /* If enough occurrences, store the exponent. */
        if (count >= 2) {
            if (terms_cnt == terms_cap) {
                size_t new_cap = terms_cap ? terms_cap * 2 : 16;
                idx_t *tmp = (idx_t*)realloc(terms, new_cap * sizeof(idx_t));
                if (!tmp) return 0;
                terms = tmp;
                terms_cap = new_cap;
            }
            terms[terms_cnt++] = current_k;
        }
    }

    return (seq_t)terms[n-1];
}
